intentos.respuesta_cruda:
{
  "sql": "SELECT COUNT(*) AS num_vendedores, SUM(ingresos) AS ingresos_totales FROM ( SELECT seller_id, SUM(price) AS ingresos, AVG(calificacion) AS calificacion, SUM(CASE WHEN entrega_tardia = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS pct_entregas_tardias FROM ( SELECT o.seller_id, o.order_id, SUM(oi.price) AS price, AVG(rv.review_score) AS calificacion, CASE WHEN oj.dias_retraso > 0 THEN 1 ELSE 0 END AS entrega_tardia FROM orders o JOIN order_items oi ON o.order_id = oi.order_id JOIN vw_entregas_retrasos oj ON oj.order_id = o.order_id LEFT JOIN order_reviews rv ON oj.order_id = rv.order_id GROUP BY o.seller_id, o.order_id ) AS subquery GROUP BY seller_id HAVING COUNT(DISTINCT order_id) >= 30 ) WHERE (calificacion < 3.5 OR pct_entregas_tardias >= 15)"
}
